const {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
  AlignmentType, BorderStyle, WidthType, ShadingType, HeadingLevel,
  LevelFormat, PageNumber, Header, Footer, TabStopType, TabStopPosition
} = require('docx');
const fs = require('fs');

const GOLD = "B8953A";
const DARK = "1A1A2E";
const LIGHT_GOLD = "F9F3E8";
const MID_GOLD = "F0E0B8";
const WHITE = "FFFFFF";
const GRAY = "666666";
const LIGHT_GRAY = "F5F5F5";

const border = { style: BorderStyle.SINGLE, size: 1, color: "D4B870" };
const borders = { top: border, bottom: border, left: border, right: border };
const noBorder = { style: BorderStyle.NONE, size: 0, color: "FFFFFF" };
const noBorders = { top: noBorder, bottom: noBorder, left: noBorder, right: noBorder };

function spacer(pts = 120) {
  return new Paragraph({ children: [new TextRun("")], spacing: { before: pts, after: 0 } });
}

function divider() {
  return new Paragraph({
    children: [new TextRun("")],
    border: { bottom: { style: BorderStyle.SINGLE, size: 8, color: GOLD, space: 1 } },
    spacing: { before: 160, after: 160 }
  });
}

function sectionLabel(text) {
  return new Paragraph({
    children: [
      new TextRun({
        text: text.toUpperCase(),
        font: "Arial",
        size: 18,
        bold: true,
        color: GOLD,
        characterSpacing: 80
      })
    ],
    spacing: { before: 280, after: 80 }
  });
}

function bodyText(text, opts = {}) {
  return new Paragraph({
    children: [
      new TextRun({
        text,
        font: "Arial",
        size: 22,
        color: opts.color || DARK,
        bold: opts.bold || false,
        italics: opts.italics || false
      })
    ],
    alignment: opts.align || AlignmentType.LEFT,
    spacing: { before: opts.before || 60, after: opts.after || 60 }
  });
}

function statBox(label, value, sub) {
  return new TableCell({
    borders,
    width: { size: 2900, type: WidthType.DXA },
    shading: { fill: LIGHT_GOLD, type: ShadingType.CLEAR },
    margins: { top: 160, bottom: 160, left: 180, right: 180 },
    children: [
      new Paragraph({
        alignment: AlignmentType.CENTER,
        children: [new TextRun({ text: value, font: "Arial", size: 56, bold: true, color: GOLD })]
      }),
      new Paragraph({
        alignment: AlignmentType.CENTER,
        children: [new TextRun({ text: label, font: "Arial", size: 18, bold: true, color: DARK })]
      }),
      new Paragraph({
        alignment: AlignmentType.CENTER,
        children: [new TextRun({ text: sub, font: "Arial", size: 16, color: GRAY, italics: true })]
      })
    ]
  });
}

function gapRow(label, desc, severity) {
  const colors = { high: "C0392B", medium: "E67E22", low: "27AE60" };
  const fills = { high: "FDECEA", medium: "FEF5E7", low: "EAFAF1" };
  return new TableRow({
    children: [
      new TableCell({
        borders,
        width: { size: 3200, type: WidthType.DXA },
        shading: { fill: fills[severity], type: ShadingType.CLEAR },
        margins: { top: 80, bottom: 80, left: 140, right: 140 },
        children: [new Paragraph({
          children: [new TextRun({ text: label, font: "Arial", size: 20, bold: true, color: colors[severity] })]
        })]
      }),
      new TableCell({
        borders,
        width: { size: 6160, type: WidthType.DXA },
        margins: { top: 80, bottom: 80, left: 140, right: 140 },
        children: [new Paragraph({
          children: [new TextRun({ text: desc, font: "Arial", size: 20, color: DARK })]
        })]
      })
    ]
  });
}

const doc = new Document({
  styles: {
    default: { document: { run: { font: "Arial", size: 22 } } }
  },
  sections: [{
    properties: {
      page: {
        size: { width: 12240, height: 15840 },
        margin: { top: 1080, right: 1080, bottom: 1080, left: 1080 }
      }
    },
    headers: {
      default: new Header({
        children: [
          new Table({
            width: { size: 10080, type: WidthType.DXA },
            columnWidths: [6000, 4080],
            rows: [new TableRow({
              children: [
                new TableCell({
                  borders: noBorders,
                  width: { size: 6000, type: WidthType.DXA },
                  children: [new Paragraph({
                    children: [new TextRun({ text: "THE LUXORA COLLECTIVE", font: "Arial", size: 18, bold: true, color: GOLD, characterSpacing: 100 })]
                  })]
                }),
                new TableCell({
                  borders: noBorders,
                  width: { size: 4080, type: WidthType.DXA },
                  children: [new Paragraph({
                    alignment: AlignmentType.RIGHT,
                    children: [new TextRun({ text: "CONFIDENTIAL MARKET SNAPSHOT", font: "Arial", size: 16, color: GRAY, italics: true })]
                  })]
                })
              ]
            })]
          }),
          new Paragraph({
            border: { bottom: { style: BorderStyle.SINGLE, size: 4, color: GOLD, space: 1 } },
            spacing: { after: 0 },
            children: [new TextRun("")]
          })
        ]
      })
    },
    children: [
      spacer(200),

      // HERO TITLE BLOCK
      new Table({
        width: { size: 10080, type: WidthType.DXA },
        columnWidths: [10080],
        rows: [new TableRow({
          children: [new TableCell({
            borders: noBorders,
            shading: { fill: DARK, type: ShadingType.CLEAR },
            width: { size: 10080, type: WidthType.DXA },
            margins: { top: 300, bottom: 300, left: 400, right: 400 },
            children: [
              new Paragraph({
                alignment: AlignmentType.CENTER,
                children: [new TextRun({ text: "YOUR MARKET SNAPSHOT", font: "Arial", size: 20, color: GOLD, bold: true, characterSpacing: 120 })]
              }),
              new Paragraph({
                alignment: AlignmentType.CENTER,
                children: [new TextRun({ text: "Doctor's Weight Loss Centers", font: "Arial", size: 44, bold: true, color: WHITE })]
              }),
              new Paragraph({
                alignment: AlignmentType.CENTER,
                children: [new TextRun({ text: "Alexandria, Virginia  |  Prepared by The Luxora Collective", font: "Arial", size: 20, color: MID_GOLD, italics: true })]
              })
            ]
          })]
        })]
      }),

      spacer(200),

      bodyText(
        "Bethany and her team reviewed your market positioning against competitors currently active in the Alexandria-area weight loss and aesthetics space. What we found is a significant opportunity that most practices in your category are leaving on the table.",
        { before: 80, after: 80 }
      ),

      divider(),

      sectionLabel("What We Looked At"),

      new Table({
        width: { size: 10080, type: WidthType.DXA },
        columnWidths: [3000, 3540, 3540],
        rows: [new TableRow({
          children: [
            statBox("Local Competitors", "14", "actively reviewed"),
            statBox("Online Touch Points", "6", "per patient journey"),
            statBox("Revenue Gaps Found", "3", "key opportunity areas")
          ]
        })]
      }),

      spacer(120),

      bodyText(
        "We analyzed your website, reviews, social presence, booking experience, and how your messaging compares to what patients are actually searching for in your market.",
        { before: 60, after: 60 }
      ),

      divider(),

      sectionLabel("What We Found: 3 Key Gaps"),

      new Table({
        width: { size: 10080, type: WidthType.DXA },
        columnWidths: [3200, 6160],
        rows: [
          new TableRow({
            children: [
              new TableCell({
                borders: { bottom: border, top: { style: BorderStyle.NONE }, left: { style: BorderStyle.NONE }, right: { style: BorderStyle.NONE } },
                shading: { fill: DARK, type: ShadingType.CLEAR },
                width: { size: 3200, type: WidthType.DXA },
                margins: { top: 80, bottom: 80, left: 140, right: 140 },
                children: [new Paragraph({ children: [new TextRun({ text: "GAP AREA", font: "Arial", size: 18, bold: true, color: WHITE, characterSpacing: 80 })] })]
              }),
              new TableCell({
                borders: { bottom: border, top: { style: BorderStyle.NONE }, left: { style: BorderStyle.NONE }, right: { style: BorderStyle.NONE } },
                shading: { fill: DARK, type: ShadingType.CLEAR },
                width: { size: 6160, type: WidthType.DXA },
                margins: { top: 80, bottom: 80, left: 140, right: 140 },
                children: [new Paragraph({ children: [new TextRun({ text: "WHAT IT MEANS FOR YOUR GROWTH", font: "Arial", size: 18, bold: true, color: WHITE, characterSpacing: 80 })] })]
              })
            ]
          }),
          gapRow("Differentiation", "Your site lists services but doesn't communicate why patients should choose YOU over competitors two miles away. The unique value of your programs isn't visible at first glance.", "high"),
          gapRow("Social Proof", "Your award-winning status and clinical results aren't prominent where potential patients are making decisions. This is leaving credibility on the table.", "high"),
          gapRow("Patient Journey", "From first click to booked appointment, there are friction points that likely cause drop-off. A competitor comparison revealed a shorter, more conversion-optimized path.", "medium")
        ]
      }),

      spacer(120),

      // HIGHLIGHT CALLOUT
      new Table({
        width: { size: 10080, type: WidthType.DXA },
        columnWidths: [10080],
        rows: [new TableRow({
          children: [new TableCell({
            borders: { left: { style: BorderStyle.SINGLE, size: 24, color: GOLD }, top: border, bottom: border, right: border },
            shading: { fill: LIGHT_GOLD, type: ShadingType.CLEAR },
            width: { size: 10080, type: WidthType.DXA },
            margins: { top: 160, bottom: 160, left: 240, right: 240 },
            children: [
              new Paragraph({
                children: [new TextRun({ text: "The good news:", font: "Arial", size: 22, bold: true, color: GOLD })]
              }),
              new Paragraph({
                children: [new TextRun({
                  text: "Every one of these gaps is fixable. And because your competitors haven't closed them either, you have a real window to be the standout practice in your market. The full report includes a prioritized 90-day roadmap specific to your practice.",
                  font: "Arial", size: 22, color: DARK
                })]
              })
            ]
          })]
        })]
      }),

      divider(),

      sectionLabel("What's In the Full Report"),

      bodyText("The complete Market Research Blueprint we prepared for Doctor's Weight Loss Centers includes:", { before: 60, after: 80 }),

      ...[
        "A full competitive landscape breakdown of your top 5 local competitors",
        "Patient journey mapping with specific drop-off points identified",
        "A visibility score across Google, social media, and online directories",
        "Specific copy and positioning recommendations for your website",
        "A 90-day prioritized growth roadmap tailored to your practice",
        "Revenue opportunity estimates based on comparable practices"
      ].map(item => new Paragraph({
        numbering: { reference: "bullets", level: 0 },
        children: [new TextRun({ text: item, font: "Arial", size: 22, color: DARK })],
        spacing: { before: 40, after: 40 }
      })),

      spacer(160),

      // CTA BOX
      new Table({
        width: { size: 10080, type: WidthType.DXA },
        columnWidths: [10080],
        rows: [new TableRow({
          children: [new TableCell({
            borders,
            shading: { fill: DARK, type: ShadingType.CLEAR },
            width: { size: 10080, type: WidthType.DXA },
            margins: { top: 240, bottom: 240, left: 400, right: 400 },
            children: [
              new Paragraph({
                alignment: AlignmentType.CENTER,
                children: [new TextRun({ text: "Ready to see the full picture?", font: "Arial", size: 28, bold: true, color: WHITE })]
              }),
              spacer(80),
              new Paragraph({
                alignment: AlignmentType.CENTER,
                children: [new TextRun({
                  text: "Bethany would love to walk you through the complete findings on a short call. No pressure, just clarity on exactly where the opportunity is.",
                  font: "Arial", size: 22, color: MID_GOLD, italics: true
                })]
              }),
              spacer(80),
              new Paragraph({
                alignment: AlignmentType.CENTER,
                children: [new TextRun({ text: "theluxoracollective.com  |  aanchal.s@theluxoracollectivemail.com", font: "Arial", size: 20, color: GOLD, bold: true })]
              })
            ]
          })]
        })]
      })
    ]
  }],
  numbering: {
    config: [
      {
        reference: "bullets",
        levels: [{
          level: 0, format: LevelFormat.BULLET, text: "\u2022", alignment: AlignmentType.LEFT,
          style: { paragraph: { indent: { left: 540, hanging: 280 } } }
        }]
      }
    ]
  }
});

Packer.toBuffer(doc).then(buffer => {
  fs.writeFileSync('/mnt/user-data/outputs/Luxora_Market_Snapshot_DoctorsWeightLoss.docx', buffer);
  console.log('Done');
});

