const {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
  AlignmentType, BorderStyle, WidthType, ShadingType, HeadingLevel,
  LevelFormat
} = require('docx');
const fs = require('fs');

const GOLD = "B8953A";
const DARK = "1A1A2E";
const LIGHT_GOLD = "F9F3E8";
const MID_GOLD = "F0E0B8";
const WHITE = "FFFFFF";
const GRAY = "666666";

const border = { style: BorderStyle.SINGLE, size: 1, color: "D4B870" };
const borders = { top: border, bottom: border, left: border, right: border };
const noBorder = { style: BorderStyle.NONE, size: 0, color: "FFFFFF" };
const noBorders = { top: noBorder, bottom: noBorder, left: noBorder, right: noBorder };

function spacer(pts = 120) {
  return new Paragraph({ children: [new TextRun("")], spacing: { before: pts, after: 0 } });
}

function divider() {
  return new Paragraph({
    children: [new TextRun("")],
    border: { bottom: { style: BorderStyle.SINGLE, size: 8, color: GOLD, space: 1 } },
    spacing: { before: 160, after: 160 }
  });
}

function sectionLabel(text) {
  return new Paragraph({
    children: [
      new TextRun({ text: text.toUpperCase(), font: "Arial", size: 18, bold: true, color: GOLD, characterSpacing: 80 })
    ],
    spacing: { before: 280, after: 100 }
  });
}

function bodyText(text, opts = {}) {
  return new Paragraph({
    children: [
      new TextRun({ text, font: "Arial", size: 22, color: opts.color || DARK, bold: opts.bold || false, italics: opts.italics || false })
    ],
    alignment: opts.align || AlignmentType.LEFT,
    spacing: { before: opts.before || 60, after: opts.after || 60 }
  });
}

function statBox(label, value, sub) {
  return new TableCell({
    borders,
    width: { size: 2900, type: WidthType.DXA },
    shading: { fill: LIGHT_GOLD, type: ShadingType.CLEAR },
    margins: { top: 160, bottom: 160, left: 180, right: 180 },
    children: [
      new Paragraph({ alignment: AlignmentType.CENTER, children: [new TextRun({ text: value, font: "Arial", size: 56, bold: true, color: GOLD })] }),
      new Paragraph({ alignment: AlignmentType.CENTER, children: [new TextRun({ text: label, font: "Arial", size: 18, bold: true, color: DARK })] }),
      new Paragraph({ alignment: AlignmentType.CENTER, children: [new TextRun({ text: sub, font: "Arial", size: 16, color: GRAY, italics: true })] })
    ]
  });
}

function gapRow(label, desc, severity) {
  const colors = { high: "C0392B", medium: "E67E22", low: "27AE60" };
  const fills = { high: "FDECEA", medium: "FEF5E7", low: "EAFAF1" };
  return new TableRow({
    children: [
      new TableCell({
        borders,
        width: { size: 3200, type: WidthType.DXA },
        shading: { fill: fills[severity], type: ShadingType.CLEAR },
        margins: { top: 100, bottom: 100, left: 140, right: 140 },
        children: [new Paragraph({ children: [new TextRun({ text: label, font: "Arial", size: 20, bold: true, color: colors[severity] })] })]
      }),
      new TableCell({
        borders,
        width: { size: 6160, type: WidthType.DXA },
        margins: { top: 100, bottom: 100, left: 140, right: 140 },
        children: [new Paragraph({ children: [new TextRun({ text: desc, font: "Arial", size: 20, color: DARK })] })]
      })
    ]
  });
}

const doc = new Document({
  styles: {
    default: { document: { run: { font: "Arial", size: 22 } } }
  },
  numbering: {
    config: [{
      reference: "bullets",
      levels: [{
        level: 0, format: LevelFormat.BULLET, text: "\u2022", alignment: AlignmentType.LEFT,
        style: { paragraph: { indent: { left: 540, hanging: 280 } } }
      }]
    }]
  },
  sections: [{
    properties: {
      page: {
        size: { width: 12240, height: 15840 },
        margin: { top: 1080, right: 1080, bottom: 1080, left: 1080 }
      }
    },
    children: [

      // HEADER BAR
      new Table({
        width: { size: 10080, type: WidthType.DXA },
        columnWidths: [6000, 4080],
        rows: [new TableRow({
          children: [
            new TableCell({
              borders: noBorders,
              width: { size: 6000, type: WidthType.DXA },
              children: [new Paragraph({ children: [new TextRun({ text: "THE LUXORA COLLECTIVE", font: "Arial", size: 18, bold: true, color: GOLD, characterSpacing: 100 })] })]
            }),
            new TableCell({
              borders: noBorders,
              width: { size: 4080, type: WidthType.DXA },
              children: [new Paragraph({ alignment: AlignmentType.RIGHT, children: [new TextRun({ text: "CONFIDENTIAL MARKET SNAPSHOT", font: "Arial", size: 16, color: GRAY, italics: true })] })]
            })
          ]
        })]
      }),
      new Paragraph({
        border: { bottom: { style: BorderStyle.SINGLE, size: 4, color: GOLD, space: 1 } },
        spacing: { after: 0 }, children: [new TextRun("")]
      }),

      spacer(200),

      // HERO BLOCK
      new Table({
        width: { size: 10080, type: WidthType.DXA },
        columnWidths: [10080],
        rows: [new TableRow({
          children: [new TableCell({
            borders: noBorders,
            shading: { fill: DARK, type: ShadingType.CLEAR },
            width: { size: 10080, type: WidthType.DXA },
            margins: { top: 300, bottom: 300, left: 400, right: 400 },
            children: [
              new Paragraph({ alignment: AlignmentType.CENTER, children: [new TextRun({ text: "YOUR MARKET SNAPSHOT", font: "Arial", size: 20, color: GOLD, bold: true, characterSpacing: 120 })] }),
              new Paragraph({ alignment: AlignmentType.CENTER, children: [new TextRun({ text: "Heron Med Spa", font: "Arial", size: 44, bold: true, color: WHITE })] }),
              new Paragraph({ alignment: AlignmentType.CENTER, children: [new TextRun({ text: "Old Town Alexandria, Virginia  |  Prepared by The Luxora Collective", font: "Arial", size: 20, color: MID_GOLD, italics: true })] })
            ]
          })]
        })]
      }),

      spacer(200),

      bodyText(
        "Bethany and her team reviewed Heron Med Spa's market positioning against competitors actively targeting your patients in the Alexandria and greater Washington, DC area. You have two decades of history, an award on the wall, and a loyal patient base. What we found is that your market doesn't know half of what you're actually capable of.",
        { before: 80, after: 80 }
      ),

      divider(),
      sectionLabel("What We Reviewed"),

      new Table({
        width: { size: 10080, type: WidthType.DXA },
        columnWidths: [3000, 3540, 3540],
        rows: [new TableRow({
          children: [
            statBox("Local Competitors", "17", "actively analyzed"),
            statBox("Services Offered", "10+", "many under-promoted"),
            statBox("Revenue Gaps Found", "4", "key opportunity areas")
          ]
        })]
      }),

      spacer(120),
      bodyText(
        "We looked at your website, online reviews, social presence, booking flow, and how your messaging stacks up against what patients in your zip code are actually searching for. We also took note of what your competitors are actively advertising that you already do, and do better.",
        { before: 60, after: 60 }
      ),

      divider(),
      sectionLabel("What We Found: 4 Key Gaps"),

      new Table({
        width: { size: 10080, type: WidthType.DXA },
        columnWidths: [3200, 6160],
        rows: [
          new TableRow({
            children: [
              new TableCell({
                borders: { bottom: border, top: noBorder, left: noBorder, right: noBorder },
                shading: { fill: DARK, type: ShadingType.CLEAR },
                width: { size: 3200, type: WidthType.DXA },
                margins: { top: 80, bottom: 80, left: 140, right: 140 },
                children: [new Paragraph({ children: [new TextRun({ text: "GAP AREA", font: "Arial", size: 18, bold: true, color: WHITE, characterSpacing: 80 })] })]
              }),
              new TableCell({
                borders: { bottom: border, top: noBorder, left: noBorder, right: noBorder },
                shading: { fill: DARK, type: ShadingType.CLEAR },
                width: { size: 6160, type: WidthType.DXA },
                margins: { top: 80, bottom: 80, left: 140, right: 140 },
                children: [new Paragraph({ children: [new TextRun({ text: "WHAT IT MEANS FOR YOUR GROWTH", font: "Arial", size: 18, bold: true, color: WHITE, characterSpacing: 80 })] })]
              })
            ]
          }),
          gapRow("Your Story Isn't Being Told", "You have 20+ years of experience, a 2015 award for the fastest-growing aesthetics practice in the Eastern US, and glowing patient results. None of that is visible in the first 10 seconds on your website.", "high"),
          gapRow("Weight Loss Is a Hidden Asset", "Competitors are actively marketing medically supervised weight loss programs in your area. Your weight loss service exists but isn't positioned to capture that growing demand, including GLP-1 adjacent patients who are actively searching.", "high"),
          gapRow("Testimonials Buried, Not Leading", "Patients have written incredible reviews about Dr. Heron and the team. Those words should be opening doors, not sitting at the bottom of a scroll. Social proof is your strongest conversion tool and it's underused.", "high"),
          gapRow("Booking Friction", "Your competitors have simplified the path from 'I'm interested' to 'I'm booked.' A review of your patient journey shows drop-off points that a few targeted fixes could close quickly.", "medium")
        ]
      }),

      spacer(120),

      // CALLOUT
      new Table({
        width: { size: 10080, type: WidthType.DXA },
        columnWidths: [10080],
        rows: [new TableRow({
          children: [new TableCell({
            borders: { left: { style: BorderStyle.SINGLE, size: 24, color: GOLD }, top: border, bottom: border, right: border },
            shading: { fill: LIGHT_GOLD, type: ShadingType.CLEAR },
            width: { size: 10080, type: WidthType.DXA },
            margins: { top: 160, bottom: 160, left: 240, right: 240 },
            children: [
              new Paragraph({ children: [new TextRun({ text: "Here's what stands out:", font: "Arial", size: 22, bold: true, color: GOLD })] }),
              new Paragraph({ children: [new TextRun({ text: "Heron Med Spa has the credentials, the results, and the longevity that newer competitors simply can't claim. The gap isn't what you offer. It's that the market doesn't fully see it yet. The full report outlines exactly how to change that, with a prioritized 90-day roadmap built around your specific practice.", font: "Arial", size: 22, color: DARK })] })
            ]
          })]
        })]
      }),

      divider(),
      sectionLabel("What's In the Full Report"),
      bodyText("The complete Market Research Blueprint prepared for Heron Med Spa includes:", { before: 60, after: 80 }),

      ...[
        "A full competitive breakdown of your top local competitors and what they're doing to win patients you should be getting",
        "A weight loss market opportunity analysis specific to the Alexandria area",
        "Your current visibility score across Google, social, and online directories",
        "Website and messaging recommendations tied to your actual services and results",
        "A social proof strategy that puts your best patient stories to work",
        "A 90-day prioritized growth roadmap with revenue opportunity estimates"
      ].map(item => new Paragraph({
        numbering: { reference: "bullets", level: 0 },
        children: [new TextRun({ text: item, font: "Arial", size: 22, color: DARK })],
        spacing: { before: 40, after: 40 }
      })),

      spacer(160),

      // CTA BOX
      new Table({
        width: { size: 10080, type: WidthType.DXA },
        columnWidths: [10080],
        rows: [new TableRow({
          children: [new TableCell({
            borders,
            shading: { fill: DARK, type: ShadingType.CLEAR },
            width: { size: 10080, type: WidthType.DXA },
            margins: { top: 240, bottom: 240, left: 400, right: 400 },
            children: [
              new Paragraph({ alignment: AlignmentType.CENTER, children: [new TextRun({ text: "Ready to see the full picture?", font: "Arial", size: 28, bold: true, color: WHITE })] }),
              spacer(80),
              new Paragraph({ alignment: AlignmentType.CENTER, children: [new TextRun({ text: "Bethany would love to walk Dr. Heron through the complete findings on a short call. 20-30 minutes. No fluff, just exactly where the opportunity is and how to move on it.", font: "Arial", size: 22, color: MID_GOLD, italics: true })] }),
              spacer(80),
              new Paragraph({ alignment: AlignmentType.CENTER, children: [new TextRun({ text: "theluxoracollective.com  |  aanchal.s@theluxoracollectivemail.com", font: "Arial", size: 20, color: GOLD, bold: true })] })
            ]
          })]
        })]
      })
    ]
  }]
});

Packer.toBuffer(doc).then(buffer => {
  fs.writeFileSync('/mnt/user-data/outputs/Luxora_Market_Snapshot_HeronMedSpa.docx', buffer);
  console.log('Done');
});

