const {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
  AlignmentType, BorderStyle, WidthType, ShadingType, LevelFormat, PageBreak
} = require('docx');
const fs = require('fs');

const GOLD = "B8953A";
const DARK = "1A1A2E";
const LIGHT_GOLD = "F9F3E8";
const MID_GOLD = "F0E0B8";
const WHITE = "FFFFFF";
const GRAY = "666666";
const LIGHT_GRAY = "F7F7F7";

const border = { style: BorderStyle.SINGLE, size: 1, color: "D4B870" };
const borders = { top: border, bottom: border, left: border, right: border };
const noBorder = { style: BorderStyle.NONE, size: 0, color: "FFFFFF" };
const noBorders = { top: noBorder, bottom: noBorder, left: noBorder, right: noBorder };

function sp(pts = 120) {
  return new Paragraph({ children: [new TextRun("")], spacing: { before: pts, after: 0 } });
}

function divider() {
  return new Paragraph({
    children: [new TextRun("")],
    border: { bottom: { style: BorderStyle.SINGLE, size: 6, color: GOLD, space: 1 } },
    spacing: { before: 180, after: 180 }
  });
}

function label(text) {
  return new Paragraph({
    children: [new TextRun({ text: text.toUpperCase(), font: "Arial", size: 18, bold: true, color: GOLD, characterSpacing: 100 })],
    spacing: { before: 260, after: 100 }
  });
}

function body(text, opts = {}) {
  return new Paragraph({
    children: [new TextRun({ text, font: "Arial", size: 22, color: opts.color || DARK, bold: opts.bold || false, italics: opts.italics || false })],
    alignment: opts.align || AlignmentType.LEFT,
    spacing: { before: opts.before || 60, after: opts.after || 60 }
  });
}

function bullet(text) {
  return new Paragraph({
    numbering: { reference: "bullets", level: 0 },
    children: [new TextRun({ text, font: "Arial", size: 22, color: DARK })],
    spacing: { before: 40, after: 40 }
  });
}

function statCell(label, value, sub) {
  return new TableCell({
    borders,
    width: { size: 3000, type: WidthType.DXA },
    shading: { fill: LIGHT_GOLD, type: ShadingType.CLEAR },
    margins: { top: 160, bottom: 160, left: 180, right: 180 },
    children: [
      new Paragraph({ alignment: AlignmentType.CENTER, children: [new TextRun({ text: value, font: "Arial", size: 52, bold: true, color: GOLD })] }),
      new Paragraph({ alignment: AlignmentType.CENTER, children: [new TextRun({ text: label, font: "Arial", size: 18, bold: true, color: DARK })] }),
      new Paragraph({ alignment: AlignmentType.CENTER, children: [new TextRun({ text: sub, font: "Arial", size: 16, color: GRAY, italics: true })] })
    ]
  });
}

// TWO COLUMN ROW: what we found + what we can do
function findingRow(findingTitle, finding, solutionTitle, solution, severity) {
  const accents = { high: "C0392B", medium: "D4830A", positive: "1A7A4A" };
  const fills = { high: "FDECEA", medium: "FEF5E7", positive: "EAF7F0" };
  return new TableRow({
    children: [
      new TableCell({
        borders,
        width: { size: 4680, type: WidthType.DXA },
        shading: { fill: fills[severity] || LIGHT_GRAY, type: ShadingType.CLEAR },
        margins: { top: 120, bottom: 120, left: 160, right: 160 },
        children: [
          new Paragraph({ children: [new TextRun({ text: findingTitle, font: "Arial", size: 20, bold: true, color: accents[severity] || DARK })] }),
          new Paragraph({ children: [new TextRun({ text: finding, font: "Arial", size: 20, color: DARK })], spacing: { before: 40 } })
        ]
      }),
      new TableCell({
        borders,
        width: { size: 4680, type: WidthType.DXA },
        shading: { fill: LIGHT_GOLD, type: ShadingType.CLEAR },
        margins: { top: 120, bottom: 120, left: 160, right: 160 },
        children: [
          new Paragraph({ children: [new TextRun({ text: solutionTitle, font: "Arial", size: 20, bold: true, color: GOLD })] }),
          new Paragraph({ children: [new TextRun({ text: solution, font: "Arial", size: 20, color: DARK })], spacing: { before: 40 } })
        ]
      })
    ]
  });
}

function tableHeader(col1, col2) {
  return new TableRow({
    children: [
      new TableCell({
        borders: { bottom: border, top: noBorder, left: noBorder, right: noBorder },
        shading: { fill: DARK, type: ShadingType.CLEAR },
        width: { size: 4680, type: WidthType.DXA },
        margins: { top: 80, bottom: 80, left: 160, right: 160 },
        children: [new Paragraph({ children: [new TextRun({ text: col1, font: "Arial", size: 18, bold: true, color: WHITE, characterSpacing: 80 })] })]
      }),
      new TableCell({
        borders: { bottom: border, top: noBorder, left: noBorder, right: noBorder },
        shading: { fill: DARK, type: ShadingType.CLEAR },
        width: { size: 4680, type: WidthType.DXA },
        margins: { top: 80, bottom: 80, left: 160, right: 160 },
        children: [new Paragraph({ children: [new TextRun({ text: col2, font: "Arial", size: 18, bold: true, color: WHITE, characterSpacing: 80 })] })]
      })
