            new TableCell({ borders: noBorders, width: { size: 5500, type: WidthType.DXA }, children: [new Paragraph({ children: [new TextRun({ text: "THE LUXORA COLLECTIVE", font: "Arial", size: 18, bold: true, color: GOLD, characterSpacing: 100 })] })] }),
            new TableCell({ borders: noBorders, width: { size: 4580, type: WidthType.DXA }, children: [new Paragraph({ alignment: AlignmentType.RIGHT, children: [new TextRun({ text: "CONFIDENTIAL MARKET SNAPSHOT", font: "Arial", size: 16, color: GRAY, italics: true })] })] })
          ]
        })]
      }),
      new Paragraph({ border: { bottom: { style: BorderStyle.SINGLE, size: 4, color: GOLD, space: 1 } }, spacing: { after: 0 }, children: [new TextRun("")] }),

