            shading: { fill: DARK, type: ShadingType.CLEAR },
            width: { size: 10080, type: WidthType.DXA },
            margins: { top: 320, bottom: 320, left: 440, right: 440 },
            children: [
              new Paragraph({ alignment: AlignmentType.CENTER, children: [new TextRun({ text: "YOUR MARKET SNAPSHOT", font: "Arial", size: 20, color: GOLD, bold: true, characterSpacing: 120 })] }),
              new Paragraph({ alignment: AlignmentType.CENTER, children: [new TextRun({ text: "Heron Med Spa", font: "Arial", size: 46, bold: true, color: WHITE })] }),
              new Paragraph({ alignment: AlignmentType.CENTER, children: [new TextRun({ text: "Old Town Alexandria, Virginia", font: "Arial", size: 22, color: MID_GOLD })] }),
